+    // Extract the command from the spec — OCI requires non-empty args
+    let cmd_args: Vec<String> = spec
+        .process()
+        .as_ref()
+        .and_then(|p| p.args().clone())
+        .filter(|args| !args.is_empty())
+        .ok_or_else(|| {
+            anyhow::anyhow!(
