+    // Write pid-file if requested (CRI-O / containerd expect this)
+    if let Some(pf) = pid_file {
+        std::fs::write(pf, child_pid.to_string())
+            .with_context(|| format!("write pid file {:?}", pf))?;
+    }
+
+    Ok(())
+}
